mod solution;

fn main() {
    let cases = [
    (r#"digits=[3,1,4]"#, r#"11"#),
    (r#"digits=[9,9]"#, r#"99"#),
    (r#"
digits=[9,9]
"#, r#"99"#),
    (r#"  
digits=[3,1,4]
  "#, r#"11"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS rolling-fingerprint");
}
